insert into core.red_flag_rules (id, code, text, published_on) values
  ('df9638f4-65e9-51e7-9c6e-859318c9ce7f', 'RF1_GROUP_CIRP', 'Insolvency (CIRP) admitted against the promoter or a group company. The band is Severe while the case stands.', null),
  ('044b899a-fb22-531a-9078-3ff434d01e5a', 'RF2_REGISTRATION_REVOKED', 'RERA registration revoked, de-registered or lapsed without an extension. Applies from the day HARERA records the revocation, or the day a registration lapses with no extension.', null),
  ('d63b2cb7-e6c3-50d5-9969-32accdc17b3c', 'RF3_STOP_SALE', 'A stop-sale or abeyance order from the regulator. Applies while the order stands. When it is lifted, the model''s band returns and the change is logged.', null),
  ('e0c480cb-a74d-56b1-9948-c26a2c9f52be', 'RF4_GROUP_DEFAULT', 'The promoter group is rated D or is in default. We quote the rating agency''s own symbol and date, exactly as published.', null);
